      gr.addColorStop(.3, s.lav ? `rgba(170,140,240,${al * .35})` : `rgba(240,180,100,${al * .35})`);
      gr.addColorStop(1, 'rgba(0,0,0,0)'); sg.fillStyle = gr; sg.fillRect(px - rr * 4, py - rr * 4, rr * 8, rr * 8);
